import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const a="/eep/ini-edit-translate-2026/editor-v2-1-37-de.png",d="/eep/ini-edit-translate-2026/info-trans-v2-1-37-de.png",s="/eep/ini-edit-translate-2026/dictionary-v2-1-37-de.png",f=JSON.parse('{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung.","frontmatter":{"title":"INI Edit Translate 2026","description":"Funktionsbeschreibung des Windows-Editors für EEP-Modell-INI-Dateien und Installation.eep mit ChatGPT-Übersetzung."},"headers":[],"relativePath":"eep/ini-edit-translate-2026/index.md","filePath":"eep/ini-edit-translate-2026/index.md","lastUpdated":1792862028000}'),l={name:"eep/ini-edit-translate-2026/index.md"};function o(u,e,h,g,c,b){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ini-edit-translate-2026" tabindex="-1">INI Edit Translate 2026 <a class="header-anchor" href="#ini-edit-translate-2026" aria-label="Permalink to &quot;INI Edit Translate 2026&quot;">​</a></h1><h2 id="version-2-1-54-bahnabkurzung-in-info-trans" tabindex="-1">Version 2.1.54: Bahnabkürzung in Info_trans <a class="header-anchor" href="#version-2-1-54-bahnabkurzung-in-info-trans" aria-label="Permalink to &quot;Version 2.1.54: Bahnabkürzung in Info_trans&quot;">​</a></h2><p>Info_trans enthält den zusätzlichen Tab <strong>Bahnabkürzung</strong> mit den 14 Einträgen Bf, Hbf, Hp, Gbf, Rbf, Abzw, BÜ, Stw, EG, OL, Gl., Bstg., DWW und Kr. Die Tabelle zeigt Deutsch, Englisch, Französisch und Polnisch einschließlich belegter fremdsprachiger Kürzel. Die bisher leere Kr.-Zeile ist als Gleiskreuzung ergänzt. Ein Klick auf eine Zelle kopiert deren Inhalt wie in den bestehenden Nachschlagetabellen. Die Tabelle ist schreibgeschützt, Spalten können sortiert werden; lange Texte werden umgebrochen. Der Tab heißt auf Englisch <strong>Railway abbreviations</strong>, auf Französisch <strong>Abréviations ferroviaires</strong>. Die Tabelle ist in Info_trans eingebettet. Eine vorhandene externe Datei <code>help/railway-abbreviations.csv</code> kann weiterhin verwendet werden. Sie ist eine Nachschlagetabelle und ändert keine automatischen Übersetzungsregeln. Vorher Backup erstellt; Wörterbuch, Datenbank, Einstellungen, Zugangsdaten und die externe Konstrukteursliste bleiben erhalten. Das Update-ZIP verwendet nur Dateipfade, die auch der Updater aus 2.1.53 akzeptiert. Download und Paketprüfung sind getrennte Schritte; 100 % wird erst nach erfolgreicher Prüfung angezeigt. Fehlerdetails stehen im Dialog, ein erneuter Versuch ist möglich. Für Visual Studio bleibt .NET Framework 4.8 erhalten. Beide Projekte verwenden einen Framework-Designer; Info_trans referenziert System.Configuration. Nach der Änderung die Projektmappe einmal neu laden. Entwurfszeit-Build und WinForms-DesignSurface wurden geprüft; Visual Studio selbst wurde nicht ferngesteuert.</p><p>114 lokale Prüfungen bestanden, einschließlich Tabelleninhalt und Oberfläche DE/EN/FR bei 100 und 150 Prozent Skalierung. Keine echten API-Anfragen.</p><h3 id="nutzerprufung-von-2-1-54" tabindex="-1">Nutzerprüfung von 2.1.54 <a class="header-anchor" href="#nutzerprufung-von-2-1-54" aria-label="Permalink to &quot;Nutzerprüfung von 2.1.54&quot;">​</a></h3><p>Am 24.10.2026 wurde das erfolgreiche Update auf 2.1.54 sowie der sichtbare Tab <strong>Bahnabkürzung</strong> vom Nutzer bestätigt. Zunächst wurde auch das Öffnen des Visual-Studio-Designers bestätigt. Anschließend wurde für den INI-Editor erneut „Der Designer konnte für diese Datei nicht angezeigt werden, da keine der enthaltenen Klassen entworfen werden kann“ gemeldet. Die Designerprüfung ist deshalb wieder offen; die erfolgreiche Update- und Tab-Prüfung bleibt bestätigt.</p><p>Die Projektzuordnung der Logikdateien <code>Form1.Update.cs</code> und <code>Form1.Translation.cs</code> wurde anschließend auf „Code“ korrigiert. Für die Oberfläche ausschließlich <code>Form1.cs</code> mit „Designer anzeigen“ öffnen, nicht die untergeordneten Logikdateien. Die Projektmappe nach Aktualisierung neu laden. Build und DesignSurface-Prüfung beider Hauptformulare bestanden; die erneute Prüfung direkt in Visual Studio steht aus.</p><p>Eine weitere Nutzermeldung nennt konkret den nicht aus <code>VsHierarchy</code> abrufbaren <code>assemblyOutputPath</code>. Der Ausgabepfad ist bei MSBuild vorhanden. Als gezielte Umgehung verwendet der AnyCPU-INI-Editor wieder den klassischen Framework-Designer (<code>UseWinFormsOutOfProcDesigner=False</code>); Info_trans behält seinen bisherigen Modus. Projektmappe nach Aktualisierung schließen und erneut öffnen, neu erstellen und <code>Form1.cs</code> im Designer öffnen. Die Bestätigung dieser Umgehung in Visual Studio steht aus.</p><h2 id="version-2-1-53-bahn-abkurzungen-und-konstrukteurskennungen" tabindex="-1">Version 2.1.53: Bahn-Abkürzungen und Konstrukteurskennungen <a class="header-anchor" href="#version-2-1-53-bahn-abkurzungen-und-konstrukteurskennungen" aria-label="Permalink to &quot;Version 2.1.53: Bahn-Abkürzungen und Konstrukteurskennungen&quot;">​</a></h2><p>20 Bahn-Abkürzungen werden jetzt anhand einer festen lokalen Zuordnung übersetzt: in Modellnamen sowie in den über den gewählten Anbieter übersetzten Texten. EW bedeutet Einfachweiche, auch ohne folgende Gradzahl. Beispiel: <code>GK3 DKW DR DB (V8)[e]EEP16.2</code> wird auf Französisch zu <code>GK3 TJD DR DB (V8)[e]EEP16.2</code>.</p><p>Die mitgelieferte Startliste enthält 272 eindeutige dreistellige Konstrukteurskennungen. Beim ersten Programmstart wird eine externe UTF-8-Datei angelegt: <code>%LOCALAPPDATA%\\UGSo\\IET2026\\constructor-codes.txt</code>. Neue Kennungen dort mit zwei Buchstaben und einer Ziffer, jeweils eine pro Zeile, ergänzen und das Programm neu starten. Updates überschreiben die Benutzerdatei nicht. Ergänzungen werden mit der mitgelieferten Grundliste zusammengeführt. Leerzeilen, Kommentare und ungültige Zeilen werden ignoriert; unlesbare Dateien bleiben erhalten und die Grundliste dient als Rückfallebene. Kennungen bleiben mit und ohne Klammern an jeder Position erhalten. Die bisherige allgemeine Erkennung weiterer Kennungen bleibt zusätzlich aktiv. DR, DB, Typbezeichnungen, Versionshinweise wie <code>(V8)</code> oder <code>(v8.2)</code>, EEP-Versionen und <code>[e]</code> bleiben unverändert.</p><table tabindex="0"><thead><tr><th>DE</th><th>EN</th><th>FR</th><th>PL</th></tr></thead><tbody><tr><td>DKW</td><td>DSS</td><td>TJD</td><td>Rkpd</td></tr><tr><td>EKW</td><td>SS</td><td>TJS</td><td>Rkp</td></tr><tr><td>EW</td><td>single turnout</td><td>BS</td><td>Rz</td></tr><tr><td>ABW</td><td>contrary-flexure turnout</td><td>ABW*</td><td>Rłd</td></tr><tr><td>IBW</td><td>similar-flexure turnout</td><td>IBW*</td><td>Rłj</td></tr><tr><td>BW</td><td>locomotive depot</td><td>dépôt de locomotives</td><td>lokomotywownia</td></tr><tr><td>Bf</td><td>station</td><td>gare</td><td>stacja</td></tr><tr><td>Hbf</td><td>main station</td><td>gare principale</td><td>dworzec główny</td></tr><tr><td>Hp</td><td>halt</td><td>halte ferroviaire</td><td>przystanek osobowy</td></tr><tr><td>Gbf</td><td>freight station</td><td>gare de marchandises</td><td>stacja towarowa</td></tr><tr><td>Rbf</td><td>marshalling yard</td><td>gare de triage</td><td>stacja rozrządowa</td></tr><tr><td>Abzw</td><td>junction</td><td>bifurcation</td><td>posterunek odgałęźny</td></tr><tr><td>BÜ</td><td>level crossing</td><td>passage à niveau</td><td>przejazd kolejowo-drogowy</td></tr><tr><td>Stw</td><td>signal box</td><td>poste d’aiguillage</td><td>nastawnia</td></tr><tr><td>EG</td><td>station building</td><td>bâtiment voyageurs</td><td>budynek dworca</td></tr><tr><td>OL</td><td>overhead line equipment</td><td>caténaire</td><td>sieć trakcyjna</td></tr><tr><td>Gl.</td><td>track</td><td>voie</td><td>tor</td></tr><tr><td>Bstg.</td><td>platform</td><td>quai</td><td>peron</td></tr><tr><td>DWW</td><td>three-way turnout</td><td>branchement à trois voies</td><td>rozjazd potrójny</td></tr><tr><td>Kr.</td><td>diamond crossing</td><td>traversée de voies</td><td>skrzyżowanie torów</td></tr></tbody></table><p>*Für ABW/IBW bleibt Französisch bis zur fachlichen Prüfung beim Originalkürzel. Die übrigen Einträge verwenden belegte Kürzel oder ausgeschriebene Übersetzungen; sie behaupten keine weltweit einheitliche Kürzelnorm. Als fremdsprachige Eingaben werden zusätzlich DS/DSS/SS, TJD/TJS/BS, Rkpd/Rkp/Rz/Rłd/Rłj, PO, Jn, PODG, LC, PN, BV und OLE erkannt. Mehrdeutiges polnisches ST/St wird nicht automatisch zugeordnet. Hp bedeutet hier Haltepunkt, Kr. bedeutet Gleiskreuzung; technische Typen wie <code>Hp0</code>, <code>DKW190</code> und Kennungen wie <code>DKW_190</code> werden nicht zerlegt.</p><p>Die geprüften Begriffe werden bei Online-Übersetzungen vorübergehend durch geschützte Platzhalter ersetzt und erst nach erfolgreicher Prüfung in der Zielsprache eingesetzt. Das funktioniert auch über die englische Zwischensprache. Fehler oder veränderte Platzhalter führen zu keiner Teilübernahme; Originaldateien, Einstellungen und Zugangsdaten bleiben erhalten. Backup vor der Änderung erstellt. MyMemory bleibt die Voreinstellung für neue Konfigurationen.</p><p>111 lokale Prüfungen bestanden, einschließlich aller 272 Kennungen, DE/EN/FR/PL, Import/Speichern/erneutem Einlesen, Versionshinweisen und Fehlerfällen. Keine echten API-Anfragen in diesen Prüfungen. Im vollständigen ZIP liegen die Zuordnung und Kontrollliste unter <code>docs/railway-glossary.md</code> und <code>docs/constructor-codes.txt</code>.</p><h2 id="version-2-1-52-beschreibende-worter-in-modellnamen" tabindex="-1">Version 2.1.52: beschreibende Wörter in Modellnamen <a class="header-anchor" href="#version-2-1-52-beschreibende-worter-in-modellnamen" aria-label="Permalink to &quot;Version 2.1.52: beschreibende Wörter in Modellnamen&quot;">​</a></h2><p>Beschreibende Wörter werden jetzt auch in Modellnamen übersetzt, selbst wenn die Modellbeschreibung leer ist. Beispiel:</p><table tabindex="0"><thead><tr><th>DE</th><th>EN</th><th>FR</th><th>PL</th></tr></thead><tbody><tr><td>Haus Helios Typ4 UD1</td><td>House Helios Typ4 UD1</td><td>Maison Helios Typ4 UD1</td><td>Dom Helios Typ4 UD1</td></tr></tbody></table><p>Zum Schutz der Eigennamen arbeitet die Namensübersetzung lokal mit einer begrenzten, geprüften Wortliste. Unbekannte Wörter und Namensbestandteile werden unverändert übernommen und nicht zur Namensübersetzung an einen Online-Dienst geschickt. Das ist keine allgemeine automatische Eigennamenerkennung: weitere beschreibende Wörter müssen geprüft ergänzt werden. Vorhandene Namen ohne erkannten beschreibenden Anteil werden nicht überschrieben. Typbezeichnungen, Konstrukteurskennungen, EEP-Versionen, <code>[e]</code>, Trennzeichen und Schreibweise geschützter Bestandteile bleiben erhalten. Die noch gesammelten Fachabkürzungen sind in dieser Änderung nicht vorweggenommen.</p><p>Beschreibungen verwenden weiterhin den gewählten Übersetzungsanbieter. Namen und Beschreibungen werden zusammen erst nach erfolgreichem Abschluss übernommen. Bei einem Fehler bleiben die bisherigen Inhalte erhalten. Der Button heißt jetzt anbieterneutral <strong>Texte übersetzen</strong>.</p><p><strong>MyMemory/translated.net ist die Voreinstellung für neue Konfigurationen.</strong> Eine bereits gespeicherte Anbieterwahl sowie API-Schlüssel, Konten und Modelle werden erhalten. Zum bewussten Wechsel <strong>Über → Einstellungen → Übersetzungseinstellungen → MyMemory → Speichern</strong> wählen.</p><p>105 lokale Prüfungen bestanden, einschließlich DE/EN/FR/PL, leerer Beschreibung, Schutz von <code>Helios Typ4 UD1 (GK3) EEP16.2[e]</code>, Fehlerverhalten und Speichern/erneutem Einlesen. Vorher Backup erstellt; Originaldateien und Zugangsdaten bleiben erhalten.</p><h2 id="version-2-1-51-hinweis-bei-ordnerauswahl" tabindex="-1">Version 2.1.51: Hinweis bei Ordnerauswahl <a class="header-anchor" href="#version-2-1-51-hinweis-bei-ordnerauswahl" aria-label="Permalink to &quot;Version 2.1.51: Hinweis bei Ordnerauswahl&quot;">​</a></h2><p>Beim Auswählen eines Ordners im Dateibaum erscheint <strong>„Bitte eine INI-Datei auswählen.“</strong> Die bereits geladenen Modelltexte, Tabellen, Vorschau und ausgewählte Datei bleiben erhalten. Ein Ordner wird nicht mehr als Datei gelesen; es startet keine Übersetzung.</p><p>Das gilt für den Hauptordner und beliebig benannte Unterordner, auch für Ordner mit <code>.ini</code> im Namen. Gelöscht gewordene Dateien und andere Dateitypen erhalten ebenfalls den Auswahlhinweis. Nur eine vorhandene INI-Datei wird geöffnet; <code>.INI</code> wird ebenfalls erkannt. Die Auswahl verwendet den ausgewählten Baumknoten statt der Mausposition und funktioniert damit auch bei Tastaturbedienung. Hinweis in Deutsch, Englisch und Französisch.</p><p>101 lokale Prüfungen bestanden, einschließlich Datenerhalt bei Ordnerauswahl in allen drei Sprachen sowie Öffnen einer INI-Datei ohne Mauspositionsprüfung. Vorher Backup erstellt; persönliche Daten und Zugangsdaten bleiben erhalten.</p><h2 id="version-2-1-50-eep-steuerzeichen-kennungen-und-versionen-schutzen" tabindex="-1">Version 2.1.50: EEP-Steuerzeichen, Kennungen und Versionen schützen <a class="header-anchor" href="#version-2-1-50-eep-steuerzeichen-kennungen-und-versionen-schutzen" aria-label="Permalink to &quot;Version 2.1.50: EEP-Steuerzeichen, Kennungen und Versionen schützen&quot;">​</a></h2><p><code>[e]</code> bleibt ein EEP-Zeilenumbruch-Steuerzeichen und wird weder übersetzt noch in einen echten Zeilenumbruch umgewandelt. Schreibweise, Anzahl und Reihenfolge der geschützten Markierungen werden geprüft.</p><p>Konstrukteurskennungen werden nach Buchstaben-/Zahlenmustern erkannt, ohne feste Namensliste. Geschützt sind beispielsweise <code>(GK3)</code>, <code>(AG3)</code>, <code>(DL1)</code> und auch ältere Schreibweisen ohne Klammern am Anfang, mitten im Text oder am Ende. Es wird keine Kennung ergänzt, wenn keine vorhanden ist. Normale Zusätze wie <code>(Winter)</code> bleiben übersetzbar. Rein aus Buchstaben bestehende Sonderkennungen lassen sich ohne eine zusätzliche Liste nicht zuverlässig von normalen Wörtern unterscheiden.</p><p>Spielversionen wie <code>EEP16.2</code>, <code>eep16.2</code> oder <code>EEP 16.2</code> bleiben einschließlich Groß-/Kleinschreibung und Satzzeichen erhalten. MyMemory erhält diese geschützten Teile nicht zur Übersetzung; bei OpenAI/ChatGPT werden veränderte oder zusätzlich erfundene Kennungen und Steuerzeichen abgelehnt. Der bestehende Rücksetzschutz bleibt aktiv.</p><p>Ein Konfigurationseintrag aus 2.1.49 verursachte beim echten App-Start einen Lesefehler. Das ist behoben und wird nun mit der ausgelieferten Konfiguration geprüft. <strong>Falls 2.1.49 nicht mehr startet:</strong> Die bisherige <code>INI Edit Translate 2026.exe.config</code> sichern. Die zusätzliche Konfigurationsdatei aus Release 2.1.50 herunterladen, in <code>INI Edit Translate 2026.exe.config</code> umbenennen und neben der EXE ersetzen. Danach starten und das normale Update auf 2.1.50 installieren. Keine INI-Dateien, Datenbanken oder persönlichen Einstellungen ersetzen.</p><p>99 lokale Prüfungen bestanden. Ein eigener Installation.eep-Test mit Kennung am Anfang, Version, Klammerkennung und zwei <code>[e]</code> wurde tatsächlich über MyMemory übersetzt, gespeichert und erneut eingelesen. Originaldateien und Zugangsdaten bleiben erhalten.</p><h2 id="version-2-1-49-letzten-pfad-erhalten" tabindex="-1">Version 2.1.49: letzten Pfad erhalten <a class="header-anchor" href="#version-2-1-49-letzten-pfad-erhalten" aria-label="Permalink to &quot;Version 2.1.49: letzten Pfad erhalten&quot;">​</a></h2><p>Unter <strong>Über → Einstellungen</strong> kann <strong>Letzten Pfad erhalten</strong> aktiviert werden. Nach <strong>Speichern</strong> bleibt der zuletzt gewählte Ordner über Neustarts und Updates erhalten. Die Ordnerliste sowie die Dialoge für Modell-INI und Installation.eep beginnen wieder dort. Dateien werden dabei nicht automatisch geöffnet oder übersetzt.</p><p>Die Option ist standardmäßig ausgeschaltet. Ist ein gespeicherter Ordner oder ein Netzlaufwerk nicht erreichbar, erscheint ein Hinweis; der gespeicherte Pfad bleibt für den nächsten Start erhalten. Vorhandene Daten und Zugangsdaten bleiben erhalten. 94 lokale Prüfungen einschließlich Speicherung/erneutem Laden, Opt-out, fehlendem Ordner und Oberfläche DE/EN/FR bei 100/150 Prozent bestanden.</p><p><strong>Version 2.1.54.0 · Windows 11 · .NET Framework 4.8</strong></p><p>INI Edit Translate 2026 bearbeitet Modellbeschreibungen und Installationsdateien für EEP. Die Anwendung wird von Uwe Grimm / UGSo Software entwickelt und unter der MIT-Lizenz veröffentlicht.</p><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026" target="_blank" rel="noreferrer">Quellcode und README auf GitHub</a></p><p><img src="'+a+'" alt="Aktuelles Design von Version 2.1.37 mit Lime-Menüleiste, ohne private Inhalte"></p><h2 id="version-2-1-48-teilset-namen-wieder-ubersetzen" tabindex="-1">Version 2.1.48: Teilset-Namen wieder übersetzen <a class="header-anchor" href="#version-2-1-48-teilset-namen-wieder-ubersetzen" aria-label="Permalink to &quot;Version 2.1.48: Teilset-Namen wieder übersetzen&quot;">​</a></h2><p>Die Namen und Beschreibungen der fünf Teilsets <code>Install_00</code> bis <code>Install_04</code> werden wieder übersetzt. Geschützt bleiben ausschließlich die Modellnamen im Modellbereich. Ausgangstexte bleiben erhalten; Deutsch und Französisch nutzen weiterhin Englisch als Zwischensprache.</p><p>Alle fünf Übersetzungsbuttons und der automatische Import verwenden dieselbe geprüfte Zuordnung. Der Button des zweiten Teilsets bearbeitet wieder dessen eigene Felder. Ein Teilset wird erst nach vollständiger Übersetzung übernommen; bei Fehler oder Abbruch bleiben seine Namen und Beschreibungen erhalten.</p><p>91 lokale Prüfungen bestanden. Ein eigener Installations-Test mit dem Namen „Detailmodell Großdiesellokomotive V140 001 DRG“ wurde tatsächlich über MyMemory übersetzt, gespeichert und erneut eingelesen; Modellnamen und ein zusätzliches INI-Feld blieben erhalten. Die Datei auf dem entfernten Spielerechner wurde dabei nicht verändert.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p><a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/download/v2.1.54/INI-Edit-Translate-2026-v2.1.54-windows.zip" target="_blank" rel="noreferrer">Windows-ZIP v2.1.54 herunterladen</a> · <a href="https://github.com/rockbaer2007/ini-edit-translate-2026/releases/tag/v2.1.54" target="_blank" rel="noreferrer">GitHub-Release und SHA-256</a></p><p>ZIP vollständig entpacken und <code>INI Edit Translate 2026.exe</code> starten. Windows 11 und .NET Framework 4.8 werden benötigt. DLLs und Sprachordner zusammen lassen. Visual Studio ist nur zum Bauen der Quellen nötig. Kein Installer erforderlich.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Möglichkeiten</th></tr></thead><tbody><tr><td>Modelltexte</td><td>Namen und Beschreibungen in EN/DE/FR/PL bearbeiten</td></tr><tr><td>Modellmetadaten</td><td>PDF-Verweise, Generation, Einsatzzeitraum, Land und Symbol bearbeiten</td></tr><tr><td>Bewegungsachsen und Signalfunktionen</td><td>Sprachabhängige Einträge anzeigen, bearbeiten und übersetzen</td></tr><tr><td>Installation.eep</td><td>Namen und Beschreibungen der unterstützten Installationsabschnitte bearbeiten</td></tr><tr><td>Vorschau</td><td>Originaldatei und erzeugte Dateivorschau vergleichen</td></tr><tr><td>Tabellenexport</td><td>Vollständige Tabellen als tabulatorgetrennte UTF-8-Dateien mit BOM exportieren</td></tr><tr><td>Sicherungen</td><td>Vor dem Überschreiben vorhandener INI-Dateien eine Kopie mit Originaldateinamen anlegen</td></tr></tbody></table><h2 id="ubersetzungsanbieter" tabindex="-1">Übersetzungsanbieter <a class="header-anchor" href="#ubersetzungsanbieter" aria-label="Permalink to &quot;Übersetzungsanbieter&quot;">​</a></h2><p>Unter <strong>Optionen → Übersetzungseinstellungen</strong> stehen OpenAI-API, ChatGPT-Abo und <strong>MyMemory</strong> zur Wahl. MyMemory benötigt Internet, aber keinen Schlüssel und kein Konto. Eine optionale E-Mail-Adresse wird mit jeder Anfrage an MyMemory gesendet: laut Anbieter 5.000 Zeichen täglich anonym, bis zu 50.000 mit gültiger E-Mail. Jede Zielsprache zählt separat; längere Texte werden in Abschnitte mit höchstens 500 UTF-8-Bytes zerlegt. Ein flüchtiger Cache vermeidet Wiederholungen innerhalb einer Aktion.</p><p>Deutsch ist die Voreinstellung. Die ausgewählte Oberfläche bestimmt die anfängliche Ausgangssprache; die Quellwahl für Achsen/Signalfunktionen bleibt bedienbar. Deutsch und Französisch werden zuerst nach Englisch übersetzt; weitere Zielsprachen entstehen aus diesem englischen Zwischenstand. Die gewählte Ausgangssprache bleibt erhalten. Das gilt für alle Anbieter. Modellnamen werden weiterhin nicht übersetzt.</p><p>MyMemory kann übermittelte Texte langfristig speichern. Die App ruft ausschließlich die Übersetzungsabfrage auf und veröffentlicht keine zusätzlichen Wörterbucheinträge. Es gibt keinen automatischen Anbieterwechsel. Bereits gespeicherte API-Schlüssel, ChatGPT-Verbindungen, Modelle und Wörterbücher bleiben erhalten. Polnische Sonderzeichen werden beim INI-Speichern über Unicode erhalten; wenn nötig wird die gesicherte Ausgabedatei in UTF-16 mit BOM gespeichert. Die reale EEP-Verarbeitung einer solchen Datei wurde hier nicht geprüft.</p><p>90 lokale Prüfungen sowie Einlesen, echte MyMemory-Übersetzung und Speichern einer Kopie der bereitgestellten Beispiel-INI wurden geprüft. Die Originaldatei bleibt unverändert. Maschinelle Fachübersetzungen vor Verwendung prüfen.</p><p><a href="https://mymemory.translated.net/doc/spec.php" target="_blank" rel="noreferrer">MyMemory API</a> · <a href="https://mymemory.translated.net/doc/usagelimits.php" target="_blank" rel="noreferrer">Kontingente</a> · <a href="https://mymemory.translated.net/terms-and-conditions" target="_blank" rel="noreferrer">Datennutzung</a></p><h2 id="einrichtung-und-bedienung" tabindex="-1">Einrichtung und Bedienung <a class="header-anchor" href="#einrichtung-und-bedienung" aria-label="Permalink to &quot;Einrichtung und Bedienung&quot;">​</a></h2><ol><li>Die Windows-ZIP über den Downloadlink herunterladen und vollständig entpacken.</li><li><code>INI Edit Translate 2026.exe</code> aus dem entpackten Ordner starten. DLLs und Sprachordner müssen bei der Anwendung bleiben.</li><li>Unter <strong>Über → Einstellungen → Übersetzungseinstellungen</strong> MyMemory, OpenAI-API oder ChatGPT-Abo wählen. Für MyMemory ist keine Anmeldung nötig; die E-Mail-Adresse ist optional.</li><li>Eine gesicherte eigene Datei zunächst im Modus <strong>Nur einlesen</strong> öffnen.</li><li>Für die Übersetzung <strong>Einlesen und übersetzen</strong> oder eine Übersetzungsschaltfläche verwenden. Bei Bewegungsachsen und Signalfunktionen die Ausgangssprache auswählen.</li><li>Vorschau und Modelltexte prüfen und anschließend ausdrücklich speichern.</li></ol><p>Der Info-Dialog wählt die geprüfte Hilfe <code>Info.de.rtf</code>, <code>Info.en.rtf</code> oder <code>Info.fr.rtf</code> passend zur Oberflächensprache. Die historische <code>Info.rtf</code> bleibt unverändert als Original erhalten. Die aktuellen Hilfetexte beschreiben OpenAI und die wiederhergestellte Nachschlagehilfe.</p><h2 id="github-updates" tabindex="-1">GitHub-Updates <a class="header-anchor" href="#github-updates" aria-label="Permalink to &quot;GitHub-Updates&quot;">​</a></h2><p>Unter <strong>Über → Nach Updates suchen</strong> wird das neueste öffentliche GitHub-Release abgefragt. Es gibt keine automatische Prüfung beim Programmstart. Nur eine neuere stabile Version wird angeboten; Versionsnummer und Release-Notizen werden angezeigt.</p><p><strong>Herunterladen und installieren</strong> lädt die Windows-ZIP samt SHA-256-Prüfsumme. Download und Paketprüfung sind abbrechbar und erfolgen vor dem Schließen der Anwendung. Vor der Installation müssen offene Dateien gespeichert und Info_trans geschlossen sein. Die Installation startet erst nach Bestätigung. Ein separates Hilfsprogramm wartet auf das Ende des Editors, sichert die bisherigen Dateien und installiert das Paket.</p><p>Einstellungen und der verschlüsselte OpenAI-Schlüssel bleiben erhalten. Vorhandene IET2.FDB-, CSV-, DAT- und Konfigurationsdateien der Nachschlagehilfe sowie die ursprüngliche Info.rtf werden gesichert und nicht ersetzt. Eigene Modelldateien bleiben unangetastet. Bei einem Installationsfehler wird die Wiederherstellung der bereits ersetzten Dateien versucht; ein Bericht nennt das Ergebnis. Sicherungen und Berichte liegen unter <code>%LOCALAPPDATA%/UGSo/IET2026/updates/&lt;Kennung&gt;/</code>.</p><p>Der Updater benötigt keine Serverzugangsdaten. Prüfsummen dienen der Integritätsprüfung; es ist keine zusätzliche digitale Paketsignatur implementiert. 36 isolierte Updateprüfungen decken Download, Abbruch, Paketpfade, Datenerhalt, gesperrte Dateien und Rücknahme nach einem teilweisen Schreibfehler ab.</p><h3 id="updater-korrektur-2-1-48" tabindex="-1">Updater-Korrektur 2.1.48 <a class="header-anchor" href="#updater-korrektur-2-1-48" aria-label="Permalink to &quot;Updater-Korrektur 2.1.48&quot;">​</a></h3><p>Die Prozessübergabe verwendet jetzt einen stabilen Windows-Prozesshandle statt Modulzugriffen auf den bereits schließenden Editor. Vier zusätzliche Prüfungen decken x86/x64, bereits beendete Prozesse, falsche Identität und Zeitüberschreitungen ab. Falls der alte 2.1.37-Helfer vor der Installation scheitert, das vollständige 2.1.48-ZIP zuerst in einen neuen Ordner entpacken. Eigene Daten vorher sichern und vorhandene Datenbanken sowie Wörterbücher nicht durch Paketdateien ersetzen.</p><p>Der vollständige Ablauf von der veröffentlichten 2.1.37 zur 2.1.48 wurde an einer gesicherten Testkopie erfolgreich geprüft: GitHub-Download, Installation und automatischer Neustart. Alle 32 bisherigen Einstellungswerte, 17 geprüfte Daten-/Modelldateien und 18 vorhandene Benutzerkonfigurationen blieben erhalten. Ein synthetischer DPAPI-Testschlüssel blieb unverändert und entschlüsselbar; anschließend wurde der ursprüngliche Zustand ohne Schlüssel wiederhergestellt. Es erfolgte kein OpenAI-Aufruf. Der Neustart wurde über Prozess-ID, Dateiversionen, Hashes und Konfiguration bestätigt; die Windows-Fenstersteuerung meldete danach einen Erfassungsfehler. Der erneute lesende GitHub-Dialogtest erkannte 2.1.48 korrekt.</p><h2 id="zweites-programm-info-trans" tabindex="-1">Zweites Programm: Info_trans <a class="header-anchor" href="#zweites-programm-info-trans" aria-label="Permalink to &quot;Zweites Programm: Info_trans&quot;">​</a></h2><p>Das Paket enthält auch <code>help/Info_trans.exe</code>. <strong>Nachschlagehilfe</strong> im Haupteditor öffnet dieses separate Programm in der gewählten Sprache. Die echte <code>IET2.FDB</code> und die zugehörige native Firebird-2.5.8-Laufzeit wurden aus dem Archiv von 2019 übernommen. Eine separate Firebird-Serverinstallation ist nicht nötig.</p><p>Die Datenbank enthält 5 Immobilien- und 2 Gütereinträge sowie 2 Updateeinträge. Die Tabellen für Signale, Rollmaterial, Gleisobjekte und Landschaft sind im Original leer. Zusätzlich sind 236 Iconeinträge, 369 technische Begriffe und 2.428 bereinigte Einträge im <strong>Wörterbuch DE/EN/FR</strong> enthalten. Englisch ist die Referenz; bestätigte deutsche Korrekturen und französische Übersetzungen sind eingearbeitet. Abgetrennte Zeilen wurden zusammengeführt und vermischte Begriffe getrennt. Amerikanische und britische Fachbegriffe bleiben mit ihren Kennzeichnungen erhalten. Alle Rückfragen zur Wörterbuchprüfung sind geklärt. Die ursprüngliche DE/EN-Datei und die Quelldatenbank bleiben unverändert im vollständigen Paket erhalten.</p><p><img src="'+d+'" alt="Info_trans 2.1.37 mit Lime-Registerkarten und geladener Originaldatenbank"></p><p><img src="'+s+'" alt="Dreisprachiges Wörterbuch in Info_trans mit gut lesbaren DE-, EN- und FR-Spalten"></p><p><code>Info_trans</code> wird passend zu den nativen DLLs für x86 gebaut. Die verwaltete DLL FirebirdSql.Data.FirebirdClient 7.5.0.0 wurde mit der echten Firebird-2.5.8-Datenbank geprüft. Tests lesen nur getrennte Datenbankkopien und vergleichen alle sieben Tabellen mit der Anzeige in DE/EN/FR. Das Paket enthält die unveränderte Quelldatenbank.</p><p>Fehlende oder nicht ladbare Bestandteile werden angezeigt. SQL-Import bleibt dann gesperrt; vor einem verfügbaren manuellen SQL-Import wird die Datenbank lokal gesichert. Die automatische Programmaktualisierung bleibt deaktiviert.</p><h2 id="daten-und-datenschutz" tabindex="-1">Daten und Datenschutz <a class="header-anchor" href="#daten-und-datenschutz" aria-label="Permalink to &quot;Daten und Datenschutz&quot;">​</a></h2><p>Die neue Fassung importiert keine alten Registrierungen oder privaten Datenbanken. Einstellungen werden getrennt pro Windows-Benutzer gespeichert. OpenAI-Konfiguration und Dateisicherungen liegen unter <code>%LOCALAPPDATA%/UGSo/IET2026/</code>.</p><p>Der Schlüssel wird für das Windows-Konto mit DPAPI verschlüsselt. Nur ausdrücklich übersetzte Texte werden an OpenAI gesendet; die API-Anfrage setzt <code>store: false</code>. Internet und separate API-Abrechnung sind erforderlich. Ein ChatGPT-Abonnement ersetzt die API-Abrechnung nicht.</p><h2 id="updatefunktion-und-prufstand" tabindex="-1">Updatefunktion und Prüfstand <a class="header-anchor" href="#updatefunktion-und-prufstand" aria-label="Permalink to &quot;Updatefunktion und Prüfstand&quot;">​</a></h2><p><strong>GitHub-Updates werden manuell gestartet und vor der Installation bestätigt.</strong> Der alte Updateserver wird nicht verwendet. Google, LEO, Linguee und DeepL werden nicht mehr angeboten.</p><p>41 lokale Prüfungen mit simulierten API-Antworten sowie Debug- und Release-Builds prüfen Fehlerfälle, Abbruch, Wiederherstellung, Tabellenexport und die gerenderten Oberflächen in DE/EN/FR. Die Tests senden keine Texte an OpenAI. Ein echter API-Aufruf und die Qualität erzeugter Modellübersetzungen sind mit dem eigenen Zugang noch zu prüfen. Nicht jedes denkbare INI-Schema wird unterstützt; die inhaltliche Prüfung bleibt notwendig.</p><p>Das vollständige lokale Release 2.1.37 wurde vor der Veröffentlichung vom Nutzer kontrolliert und als funktionsfähig bestätigt. Das ZIP enthält beide Programme, die native Firebird-Laufzeit, die Originaldatenbank und das korrigierte Wörterbuch. ZIP-Integrität und SHA-256 wurden geprüft, alle sieben Datenbanktabellen wurden auf getrennten Kopien mit der Anzeige in DE/EN/FR verglichen. Die Bilder zeigen das aktuelle Design mit neutralen Daten und ohne private Einstellungen.</p>',79)])])}const m=n(l,[["render",o]]);export{f as __pageData,m as default};
